mapper.insert:
insert into xray_payment_order (
    user_id, packet_id, order_no, submit_token, type, amount, currency, status, notify_url, return_url, payment_url,
    trade_no, paid_amount, paid_currency, paid_at, success_at, created_at, updated_at, expired_at
)
values (
    #{userId}, #{packetId}, #{orderNo}, #{submitToken}, #{type}, #{amount}, #{currency}, #{status}, #{notifyUrl}, #{returnUrl}, #{paymentUrl},
    #{tradeNo}, #{paidAmount}, #{paidCurrency}, #{paidAt}, #{successAt}, #{createdAt}, #{updatedAt}, #{expiredAt}
)

mapper.select:
select id, user_id, packet_id, order_no, submit_token, type, amount, currency, status, notify_url, return_url, payment_url,
       trade_no, paid_amount, paid_currency, paid_at, success_at, created_at, updated_at, expired_at
from xray_payment_order


        AND order_no like concat('%', #{orderNo}, '%')


        AND type = #{type}


        AND status = #{status}


        AND packet_id = #{packetId}


        AND user_id = #{userId}


        AND created_at >= #{params.beginTime}


        AND created_at <= #{params.endTime}


order by created_at desc, id desc

select id, user_id, packet_id, order_no, submit_token, type, amount, currency, status, notify_url, return_url, payment_url,
       trade_no, paid_amount, paid_currency, paid_at, success_at, created_at, updated_at, expired_at
from xray_payment_order
where user_id = #{userId}
  and packet_id = #{packetId}
  and type = #{type}
  and amount = #{amount}
  and currency = #{currency}
  and status = 'PENDING'
  and expired_at > NOW()
order by id desc
limit 1

mapper.update:
update xray_payment_order
set
    status = #{status},
    updated_at = #{updatedAt}
where order_no = #{orderNo}

update xray_payment_order
status = #{status}, submit_token = #{submitToken}, currency = #{currency}, payment_url = #{paymentUrl}, notify_url = #{notifyUrl}, return_url = #{returnUrl}, trade_no = #{tradeNo}, paid_amount = #{paidAmount}, paid_currency = #{paidCurrency}, paid_at = #{paidAt}, success_at = #{successAt}, expired_at = #{expiredAt}, updated_at = NOW()
where order_no = #{orderNo}
